juce::AudioProcessorValueTreeState::ParameterLayout WorldProcessor::layout(){juce::AudioProcessorValueTreeState::ParameterLayout l;for(int pad=0;pad<16;pad++)for(auto&s:world::specs){juce::String key="pad"+juce::String(pad+1)+"_"+s.id;juce::ParameterID pid(key,1);juce::String name="Pad "+juce::String(pad+1)+" "+s.name;if(s.choices[0])l.add(std::make_unique<juce::AudioParameterChoice>(pid,name,juce::StringArray::fromTokens(s.choices,"|",""),(int)s.initial));else l.add(std::make_unique<juce::AudioParameterFloat>(pid,name,juce::NormalisableRange<float>(s.lo,s.hi,s.step,s.skew),s.initial));}
 l.add(std::make_unique<juce::AudioParameterBool>(juce::ParameterID("auto",1),"Autoplay",false));l.add(std::make_unique<juce::AudioParameterFloat>(juce::ParameterID("tempo",1),"Autoplay BPM",40,220,110));l.add(std::make_unique<juce::AudioParameterChoice>(juce::ParameterID("division",1),"Autoplay division",juce::StringArray{"1/8","1/16","1/16 triplet","1/32"},1));l.add(std::make_unique<juce::AudioParameterFloat>(juce::ParameterID("shuffle",1),"Shuffle percent",0,60,0));l.add(std::make_unique<juce::AudioParameterBool>(juce::ParameterID("host",1),"DAW transport sync",false));l.add(std::make_unique<juce::AudioParameterFloat>(juce::ParameterID("master",1),"Master output dB",-36,0,-6));l.add(std::make_unique<juce::AudioParameterChoice>(juce::ParameterID("midiMode",1),"MIDI routing",juce::StringArray{"Keyboard + ch10 pads","Pad controller (any channel)"},0));return l;}
